"""
patch_metrics_daemon.py — Спринт 22
Добавляет в metrics_daemon.py логику сигнала Демона:
  - _handle_daemon_signal() — хороший/плохой сигнал → резерв
  - _is_good_signal()       — нулевой пульс = плохой сигнал
  - _release_reserve_idea() — выпускает следующую идею из резерва
  - _add_to_pending()       — добавляет резервный пост в очередь
  - conflict_run_id/phase_id/slot_id пробрасываются из pending_posts
Запуск: python patch_metrics_daemon.py
"""
import shutil, subprocess
from pathlib import Path

TARGET = Path("studio/economy/metrics_daemon.py")
NEW_CONTENT = '# studio/economy/metrics_daemon.py\n# Студия «Шесть Пальцев» · 2026 · Спринт 22\n#\n# Metrics Daemon — независимый фоновый процесс.\n# Единственная ответственность: забрать реальные метрики → закрыть петлю.\n#\n# Алгоритм одного прохода:\n#   1. Обойти всех клиентов (clients/*/pending_posts.json)\n#   2. Найти посты со статусом "published" у которых прошло > 24ч\n#   3. Запросить метрики из API соцсети\n#   4. Посчитать real_viral_score\n#   5. Вызвать ministry.record_outcome\n#   6. [v2] Сигнал Демона → закрыть резерв (хороший) или достать следующую идею (плохой)\n#   7. Сравнить с прогнозом Тима, записать разницу\n#   8. Обновить статус поста → "scored"\n#\n# Запуск:\n#   python studio/economy/metrics_daemon.py\n#   python studio/economy/metrics_daemon.py --interval 3600\n#   python studio/economy/metrics_daemon.py --once\n\nfrom __future__ import annotations\n\nimport json\nimport sys\nimport time\nimport threading\nimport argparse\nfrom datetime import datetime, timezone, timedelta\nfrom pathlib import Path\n\nCLIENTS_DIR      = Path("clients")\nDEFAULT_INTERVAL = 3600\nMATURITY_HOURS   = 24\n\n\n# ═══════════════════════════════════════════════════════════════\n# ГЛАВНЫЙ ЦИКЛ\n# ═══════════════════════════════════════════════════════════════\n\ndef run_forever(interval_sec: int = DEFAULT_INTERVAL) -> None:\n    print(f"[DAEMON] Запущен. Интервал: {interval_sec}с. Порог созревания: {MATURITY_HOURS}ч.")\n    while True:\n        try:\n            processed = check_all_clients()\n            if processed:\n                print(f"[DAEMON] Обработано постов: {processed}")\n            else:\n                print(f"[DAEMON] Нет созревших постов. Следующая проверка через {interval_sec}с.")\n        except Exception as e:\n            print(f"[DAEMON] Ошибка прохода: {e}")\n        time.sleep(interval_sec)\n\n\ndef start_background(interval_sec: int = DEFAULT_INTERVAL) -> threading.Thread:\n    """\n    Запускает демон в фоновом потоке.\n    Вызывай из main.py при старте студии:\n        from studio.economy.metrics_daemon import start_background\n        start_background()\n    """\n    t = threading.Thread(\n        target=run_forever,\n        kwargs={"interval_sec": interval_sec},\n        daemon=True,\n        name="MetricsDaemon",\n    )\n    t.start()\n    print("[DAEMON] Фоновый поток запущен (MetricsDaemon)")\n    return t\n\n\n# ═══════════════════════════════════════════════════════════════\n# ОДИН ПРОХОД\n# ═══════════════════════════════════════════════════════════════\n\ndef check_all_clients() -> int:\n    if not CLIENTS_DIR.exists():\n        return 0\n    total = 0\n    for client_dir in CLIENTS_DIR.iterdir():\n        if not client_dir.is_dir():\n            continue\n        pending_file = client_dir / "pending_posts.json"\n        if not pending_file.exists():\n            continue\n        total += _process_client(client_dir.name, pending_file)\n    return total\n\n\ndef _process_client(client_id: str, pending_file: Path) -> int:\n    try:\n        posts = json.loads(pending_file.read_text(encoding="utf-8"))\n    except Exception as e:\n        print(f"[DAEMON] {client_id}: не могу прочитать pending_posts.json: {e}")\n        return 0\n\n    cfg = _load_social_config(client_id)\n    if not cfg:\n        return 0\n\n    now       = datetime.now(timezone.utc)\n    threshold = timedelta(hours=MATURITY_HOURS)\n    processed = 0\n    changed   = False\n\n    for entry in posts:\n        if entry.get("status") != "published":\n            continue\n\n        try:\n            pub_dt = datetime.fromisoformat(entry["published_at"])\n        except (KeyError, ValueError):\n            continue\n\n        if now - pub_dt < threshold:\n            remaining = threshold - (now - pub_dt)\n            h = int(remaining.total_seconds() // 3600)\n            m = int((remaining.total_seconds() % 3600) // 60)\n            print(f"[DAEMON] {client_id}/{entry[\'project_id\']}: созреет через {h}ч {m}мин")\n            continue\n\n        platform = entry["platform"]\n        metrics  = _fetch_metrics(entry, cfg)\n\n        if not metrics:\n            print(f"[DAEMON] {client_id}/{entry[\'project_id\']}: метрики недоступны")\n            continue\n\n        real_score = _calc_score(metrics, platform, cfg.get("score_weights", {}))\n        tim_score  = entry.get("tim_forecast")\n\n        print(f"[DAEMON] {client_id}/{entry[\'project_id\']}: реальный={real_score} | прогноз Тима={tim_score}")\n\n        # Министерство\n        _report_to_ministry(client_id, platform, real_score, entry["project_id"])\n\n        # [v2] Сигнал Демона — резерв\n        run_id   = entry.get("conflict_run_id", "")\n        phase_id = entry.get("conflict_phase_id", "")\n        slot_id  = entry.get("slot_id", "")\n        if run_id and phase_id:\n            _handle_daemon_signal(\n                run_id=run_id,\n                phase_id=phase_id,\n                slot_id=slot_id,\n                real_score=real_score,\n                metrics=metrics,\n                platform=platform,\n                entry=entry,\n                cfg=cfg,\n            )\n\n        # Обновляем запись\n        entry["status"]           = "scored"\n        entry["scored_at"]        = now.isoformat()\n        entry["real_metrics"]     = metrics\n        entry["real_viral_score"] = real_score\n        if tim_score is not None:\n            entry["forecast_delta"] = round(real_score - float(tim_score), 2)\n\n        _patch_final_dna(client_id, entry["project_id"], real_score)\n\n        processed += 1\n        changed    = True\n\n    if changed:\n        pending_file.write_text(\n            json.dumps(posts, ensure_ascii=False, indent=2), encoding="utf-8"\n        )\n\n    return processed\n\n\n# ═══════════════════════════════════════════════════════════════\n# СИГНАЛ ДЕМОНА — главная новая логика v2\n# ═══════════════════════════════════════════════════════════════\n\ndef _handle_daemon_signal(\n    run_id: str,\n    phase_id: str,\n    slot_id: str,\n    real_score: float,\n    metrics: dict,\n    platform: str,\n    entry: dict,\n    cfg: dict,\n) -> None:\n    """\n    Демон оценивает сигнал и решает судьбу резерва.\n\n    Хороший сигнал → close_run_reserve():\n        резерв закрывается, опыт уходит в interaction_log,\n        победитель записывается в daemon_wins (культура цеха).\n\n    Плохой сигнал → consume_from_reserve():\n        следующая идея из резерва идёт в мир через лёгкий прогон финализатора.\n        Мутации получают приоритет.\n    """\n    try:\n        from studio.economy.conflict_memory import (\n            get_run_reserve,\n            consume_from_reserve,\n            close_run_reserve,\n        )\n    except ImportError as e:\n        print(f"[DAEMON] conflict_memory недоступен: {e}")\n        return\n\n    reserve = get_run_reserve(run_id, phase_id)\n    if not reserve:\n        return  # резерв уже закрыт или не существует\n\n    released_agent = reserve.get("released_agent_id", "unknown")\n\n    if _is_good_signal(real_score, metrics, platform):\n        print(f"[DAEMON] Хороший сигнал (score={real_score}) — закрываю резерв {run_id}")\n        close_run_reserve(\n            run_id=run_id,\n            phase_id=phase_id,\n            winning_agent_id=released_agent,\n            viral_score=real_score,\n            slot_id=slot_id,\n        )\n    else:\n        print(f"[DAEMON] Плохой сигнал (score={real_score}) — достаю из резерва {run_id}")\n        next_idea = consume_from_reserve(run_id, phase_id)\n        if next_idea:\n            _release_reserve_idea(next_idea, entry, cfg, platform, slot_id)\n        else:\n            print(f"[DAEMON] Резерв {run_id} исчерпан — больше идей нет")\n            # Исчерпан — всё равно закрываем, победитель не определён\n            close_run_reserve(\n                run_id=run_id,\n                phase_id=phase_id,\n                winning_agent_id=released_agent,\n                viral_score=real_score,\n                slot_id=slot_id,\n            )\n\n\ndef _is_good_signal(real_score: float, metrics: dict, platform: str) -> bool:\n    """\n    Хороший сигнал = есть реальная реакция зрителя.\n    Плохой сигнал = нулевой пульс за 24 часа.\n\n    На старте (нет истории): простая эвристика по метрикам.\n    В будущем Ministry добавит сравнение с нормой цеха.\n\n    Нулевой пульс для Telegram: views < 50 AND forwards == 0 AND reactions == 0\n    Нулевой пульс для VK:       likes == 0 AND reposts == 0 AND comments == 0\n    """\n    if platform == "telegram":\n        views     = metrics.get("views", 0)\n        forwards  = metrics.get("forwards", 0)\n        reactions = metrics.get("reactions", 0)\n        flat = (views < 50) and (forwards == 0) and (reactions == 0)\n        return not flat\n\n    elif platform == "vk":\n        likes    = metrics.get("likes", 0)\n        reposts  = metrics.get("reposts", 0)\n        comments = metrics.get("comments", 0)\n        flat = (likes == 0) and (reposts == 0) and (comments == 0)\n        return not flat\n\n    # Для YouTube и других — по score\n    return real_score >= 1.0\n\n\ndef _release_reserve_idea(\n    next_idea: dict,\n    original_entry: dict,\n    cfg: dict,\n    platform: str,\n    slot_id: str,\n) -> None:\n    """\n    Выпускает следующую идею из резерва в мир.\n\n    Не запускает полный CartridgeRunner — это лёгкий прогон:\n    идея уже готова (intent + human_text), нужно только опубликовать\n    через broadcaster с контекстом "первый не выжил".\n\n    Если broadcaster недоступен — сохраняет идею в pending как новый пост.\n    """\n    agent_id    = next_idea["agent_id"]\n    intent      = next_idea["intent"]\n    is_mutation = next_idea.get("is_mutation", False)\n    attempt     = next_idea.get("attempt_number", 2)\n\n    mutation_marker = " [МУТАЦИЯ]" if is_mutation else ""\n    print(\n        f"[DAEMON] Выпускаю резервную идею: агент={agent_id}"\n        f"{mutation_marker}, попытка={attempt}"\n    )\n\n    # Пробуем через broadcaster\n    try:\n        from studio.assembly.broadcaster import publish_text\n        result = publish_text(\n            text=next_idea.get("human_text", intent),\n            platform=platform,\n            cfg=cfg,\n            meta={\n                "source":       "reserve",\n                "agent_id":     agent_id,\n                "attempt":      attempt,\n                "is_mutation":  is_mutation,\n                "run_id":       next_idea.get("run_id", ""),\n                "slot_id":      slot_id,\n                "note":         f"Резервная идея (попытка {attempt}). Первая не выжила у зрителя.",\n            },\n        )\n        if result:\n            print(f"[DAEMON] Резервная идея опубликована через broadcaster")\n            # Добавляем в pending_posts для следующей проверки Демона\n            _add_to_pending(\n                client_id=original_entry.get("client_id", ""),\n                post_id=result.get("post_id", ""),\n                platform=platform,\n                project_id=f"{original_entry.get(\'project_id\', \'\')}__reserve_{attempt}",\n                conflict_run_id=next_idea.get("run_id", ""),\n                conflict_phase_id=next_idea.get("phase_id", ""),\n                slot_id=slot_id,\n            )\n            return\n    except ImportError:\n        print("[DAEMON] broadcaster недоступен — сохраняю идею в очередь")\n    except Exception as e:\n        print(f"[DAEMON] Ошибка публикации через broadcaster: {e}")\n\n    # Fallback — сохраняем в файл для ручного запуска\n    fallback_path = Path("studio/economy/data") / f"reserve_pending_{next_idea.get(\'run_id\', \'unknown\')}.json"\n    fallback_path.write_text(\n        json.dumps(next_idea, ensure_ascii=False, indent=2),\n        encoding="utf-8",\n    )\n    print(f"[DAEMON] Резервная идея сохранена: {fallback_path}")\n\n\ndef _add_to_pending(\n    client_id: str,\n    post_id: str,\n    platform: str,\n    project_id: str,\n    conflict_run_id: str,\n    conflict_phase_id: str,\n    slot_id: str,\n) -> None:\n    """Добавляет опубликованный резервный пост в pending_posts для следующей проверки."""\n    if not client_id or not post_id:\n        return\n    pending_file = CLIENTS_DIR / client_id / "pending_posts.json"\n    try:\n        posts = json.loads(pending_file.read_text(encoding="utf-8")) if pending_file.exists() else []\n    except Exception:\n        posts = []\n\n    posts.append({\n        "status":            "published",\n        "published_at":      datetime.now(timezone.utc).isoformat(),\n        "post_id":           post_id,\n        "platform":          platform,\n        "project_id":        project_id,\n        "conflict_run_id":   conflict_run_id,\n        "conflict_phase_id": conflict_phase_id,\n        "slot_id":           slot_id,\n        "source":            "reserve",\n    })\n    pending_file.write_text(json.dumps(posts, ensure_ascii=False, indent=2), encoding="utf-8")\n\n\n# ═══════════════════════════════════════════════════════════════\n# ПОЛУЧЕНИЕ МЕТРИК\n# ═══════════════════════════════════════════════════════════════\n\ndef _fetch_metrics(entry: dict, cfg: dict) -> dict:\n    platform   = entry["platform"]\n    post_id    = entry["post_id"]\n    channel_id = entry.get("channel_id", "")\n\n    if platform == "telegram":\n        token = cfg["platforms"]["telegram"].get("bot_token", "")\n        chan  = channel_id or cfg["platforms"]["telegram"].get("channel_id", "")\n        return _fetch_telegram(post_id, chan, token)\n    elif platform == "vk":\n        token    = cfg["platforms"]["vk"].get("token", "")\n        owner_id = channel_id or cfg["platforms"]["vk"].get("owner_id", "")\n        return _fetch_vk(post_id, owner_id, token)\n    return {}\n\n\ndef _fetch_telegram(post_id: str, channel_id: str, token: str) -> dict:\n    if not token or not channel_id:\n        return {}\n    try:\n        import requests\n        base = f"https://api.telegram.org/bot{token}"\n        r    = requests.get(f"{base}/getMessages", params={\n            "chat_id":     channel_id,\n            "message_ids": json.dumps([int(post_id)]),\n        }, timeout=15).json()\n        if r.get("ok") and r.get("result"):\n            m = r["result"][0]\n            return {\n                "views":     m.get("views", 0),\n                "forwards":  m.get("forwards", 0),\n                "reactions": sum(\n                    x.get("count", 0)\n                    for x in m.get("reactions", {}).get("reactions", [])\n                ),\n            }\n    except Exception as e:\n        print(f"[DAEMON] Telegram fetch error: {e}")\n    return {}\n\n\ndef _fetch_vk(post_id: str, owner_id: str, token: str) -> dict:\n    if not token or not owner_id:\n        return {}\n    try:\n        import requests\n        r = requests.get("https://api.vk.com/method/wall.getById", params={\n            "posts":        f"{owner_id}_{post_id}",\n            "access_token": token,\n            "v":            "5.199",\n        }, timeout=15).json()\n        if "response" in r and r["response"]:\n            p = r["response"][0]\n            return {\n                "views":    p.get("views",    {}).get("count", 0),\n                "likes":    p.get("likes",    {}).get("count", 0),\n                "reposts":  p.get("reposts",  {}).get("count", 0),\n                "comments": p.get("comments", {}).get("count", 0),\n            }\n    except Exception as e:\n        print(f"[DAEMON] VK fetch error: {e}")\n    return {}\n\n\n# ═══════════════════════════════════════════════════════════════\n# ПОДСЧЁТ VIRAL_SCORE\n# ═══════════════════════════════════════════════════════════════\n\n_DEFAULT_WEIGHTS = {\n    "telegram": {\n        "views_per_point": 500,    "views_max_points": 4.0,\n        "forwards_per_point": 5,   "forwards_max_points": 3.0,\n        "reactions_per_point": 20, "reactions_max_points": 3.0,\n    },\n    "vk": {\n        "views_per_point": 1000,   "views_max_points": 3.0,\n        "likes_per_point": 20,     "likes_max_points": 3.0,\n        "reposts_per_point": 5,    "reposts_max_points": 2.5,\n        "comments_per_point": 10,  "comments_max_points": 1.5,\n    },\n}\n\n\ndef _calc_score(metrics: dict, platform: str, weights: dict) -> float:\n    cfg   = weights.get(platform) or _DEFAULT_WEIGHTS.get(platform, {})\n    score = 0.0\n\n    def _add(metric_key, per_key, max_key):\n        nonlocal score\n        val = metrics.get(metric_key, 0)\n        per = max(cfg.get(per_key, 1), 1)\n        mx  = float(cfg.get(max_key, 3.0))\n        score += min(mx, val / per)\n\n    if platform == "telegram":\n        _add("views",     "views_per_point",     "views_max_points")\n        _add("forwards",  "forwards_per_point",  "forwards_max_points")\n        _add("reactions", "reactions_per_point", "reactions_max_points")\n    elif platform == "vk":\n        _add("views",    "views_per_point",    "views_max_points")\n        _add("likes",    "likes_per_point",    "likes_max_points")\n        _add("reposts",  "reposts_per_point",  "reposts_max_points")\n        _add("comments", "comments_per_point", "comments_max_points")\n\n    return round(min(10.0, score), 2)\n\n\n# ═══════════════════════════════════════════════════════════════\n# MINISTRY\n# ═══════════════════════════════════════════════════════════════\n\ndef _report_to_ministry(client_id: str, platform: str,\n                         real_score: float, project_id: str) -> None:\n    try:\n        sys.path.insert(0, str(Path(__file__).parents[2]))\n        from studio.economy import ministry\n        ministry.record_outcome("A06",      f"{platform}_fal", real_score, cost_usd=0.0)\n        ministry.record_outcome("pipeline", "social_mix",      real_score, cost_usd=0.0)\n        print(f"[DAEMON] Ministry обновлён: {project_id} → score={real_score}")\n    except Exception as e:\n        print(f"[DAEMON] ministry.record_outcome: {e}")\n\n\n# ═══════════════════════════════════════════════════════════════\n# ПАТЧ FINAL_DNA\n# ═══════════════════════════════════════════════════════════════\n\ndef _patch_final_dna(client_id: str, project_id: str, real_score: float) -> None:\n    search = [CLIENTS_DIR / client_id / "jobs", Path("runs"), Path("output")]\n    for base in search:\n        for match in base.glob(f"*{project_id}*"):\n            if not match.is_dir():\n                continue\n            p = match / "claudia_final.json"\n            if p.exists():\n                try:\n                    data = json.loads(p.read_text(encoding="utf-8"))\n                    data.setdefault("final_dna", {})["real_viral_score"] = real_score\n                    data.setdefault("final_dna", {})["status"]           = "scored"\n                    data.setdefault("claudia_final", {})["status"]       = "scored"\n                    p.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")\n                except Exception as e:\n                    print(f"[DAEMON] patch_final_dna: {e}")\n                return\n\n\n# ═══════════════════════════════════════════════════════════════\n# КОНФИГ\n# ═══════════════════════════════════════════════════════════════\n\ndef _load_social_config(client_id: str) -> dict | None:\n    p = CLIENTS_DIR / client_id / "social_config.json"\n    if not p.exists():\n        return None\n    try:\n        return json.loads(p.read_text(encoding="utf-8"))\n    except Exception:\n        return None\n\n\n# ═══════════════════════════════════════════════════════════════\n# CLI\n# ═══════════════════════════════════════════════════════════════\n\nif __name__ == "__main__":\n    parser = argparse.ArgumentParser(description="Metrics Daemon — сборщик реальных метрик")\n    parser.add_argument("--interval", type=int, default=DEFAULT_INTERVAL,\n                        help=f"интервал между проходами в секундах (default: {DEFAULT_INTERVAL})")\n    parser.add_argument("--once", action="store_true", help="один проход и выход")\n    args = parser.parse_args()\n\n    if args.once:\n        n = check_all_clients()\n        print(f"[DAEMON] Готово. Обработано: {n}")\n    else:\n        run_forever(args.interval)\n'

def apply_patch():
    if not TARGET.exists():
        print(f"[PATCH] Файл не найден: {TARGET}")
        return False
    bak = TARGET.with_suffix(".bak_sprint22")
    shutil.copy2(TARGET, bak)
    print(f"[PATCH] Бэкап: {bak}")
    TARGET.write_text(NEW_CONTENT, encoding="utf-8")
    print("[PATCH] metrics_daemon.py обновлён")
    result = subprocess.run(["python", "-m", "py_compile", str(TARGET)], capture_output=True, text=True)
    if result.returncode == 0:
        print("[PATCH] Синтаксис OK")
        return True
    print(f"[PATCH] Синтаксис ERROR:\n{result.stderr}")
    shutil.copy2(bak, TARGET)
    return False

if __name__ == "__main__":
    apply_patch()
